// Generated by /ship coverage audit (Claude Opus 5.5) — 2026-10-15
// Value: protects=the /student-care route loads the students list only on the two assignment tabs (inactive flag, trimmed search, page from the URL) and the task route wires view/handle/assign and its notFound/error states;
// fails_when=the inactive flag is inverted, students load on the tasks tab, a repeated or padded URL value reaches the loaders, or canHandle is wired to the wrong permission;
// why_new=pass-1 gap G1: only CareQueueView/CareDetailView are rendered in tests, never the route files that build their props; seam=none (loaders, permissions and next/navigation mocked);
// no_claim=does not run the RPCs or prove the RPCs' own page size and search handling
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import StudentCareDetail from "@/app/(app)/student-care/[taskId]/page";
import StudentCarePage from "@/app/(app)/student-care/page";
import type { CareDashboard, CareDetail, CareStudents } from "@/features/student-care/models";

const mocks = vi.hoisted(() => ({
  dashboard: vi.fn(),
  detail: vi.fn(),
  permissions: vi.fn(),
  students: vi.fn(),
  user: vi.fn(),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({ getCachedDatabasePermissions: mocks.permissions }));
vi.mock("@/features/auth/current-user", () => ({ getCachedCurrentAuthUser: mocks.user }));
vi.mock("@/features/student-care/data", () => ({ getCareDashboard: mocks.dashboard, getCareDetail: mocks.detail, getCareStudents: mocks.students }));
vi.mock("@/features/student-care/actions", () => ({ mutateCare: vi.fn() }));
vi.mock("next/navigation", () => ({
  notFound: vi.fn(() => {
    throw new Error("NEXT_NOT_FOUND");
  }),
  usePathname: () => "/student-care",
  useRouter: () => ({ push: vi.fn(), refresh: vi.fn(), replace: vi.fn() }),
  useSearchParams: () => new URLSearchParams(),
}));

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

const ME = "11111111-1111-4111-8111-111111111111";
const TASK = "55555555-5555-4555-8555-555555555555";
const STUDENT = "33333333-3333-4333-8333-333333333333";

const dashboard: CareDashboard = {
  assignees: [{ id: ME, name: "Đặng Phương Thảo", open_tasks: 0 }],
  month: "2026-10-01",
  page: 1,
  queue: { failed: 0, pending: 0 },
  rows: [],
  settings: { enabled: true, last_error: null, last_reconcile_at: null, last_success_at: new Date().toISOString() },
  summary: { monthly_cancelled: 0, monthly_completed: 0, monthly_on_time: 0, monthly_total: 0, open_alerts: 0, overdue: 0, unassigned: 0 },
  total: 0,
};
const students: CareStudents = {
  rows: [{ full_name: "Phạm Khánh Linh", id: STUDENT, lifecycle_status: "paused", owner_id: null, owner_name: null, public_code: "TTV-00200" }],
  total: 1,
};

function allow(...codes: string[]) {
  mocks.permissions.mockResolvedValue({ ok: true, permissions: ["student_care.view", ...codes] });
}

describe("/student-care route", () => {
  it("loads students only on the assignment tabs, with the URL's first value, trimmed search and page", async () => {
    allow("student_care.handle");
    mocks.dashboard.mockResolvedValue(dashboard);
    mocks.students.mockResolvedValue(students);

    render(await StudentCarePage({ searchParams: Promise.resolve({ page: "2", search: "  Linh ", tab: ["inactive", "assignments"] }) }));
    expect(mocks.students).toHaveBeenCalledExactlyOnceWith("Linh", 2, true);
    expect(mocks.dashboard).toHaveBeenCalledWith(expect.objectContaining({ page: 2, search: "Linh" }));
    expect(screen.getAllByRole("link", { name: "Phạm Khánh Linh" }).length).toBeGreaterThan(0);
    expect(screen.getAllByRole("button", { name: "Tạo lịch theo dõi" }).length).toBeGreaterThan(0);
    cleanup();
    vi.clearAllMocks();

    allow("student_care.handle");
    mocks.dashboard.mockResolvedValue(dashboard);
    mocks.students.mockResolvedValue(students);
    render(await StudentCarePage({ searchParams: Promise.resolve({ tab: "assignments" }) }));
    expect(mocks.students).toHaveBeenCalledExactlyOnceWith("", 1, false);
    cleanup();
    vi.clearAllMocks();

    allow("student_care.handle");
    mocks.dashboard.mockResolvedValue(dashboard);
    render(await StudentCarePage({ searchParams: Promise.resolve({ kind: "alert", tab: "bogus" }) }));
    expect(mocks.students).not.toHaveBeenCalled();
    expect(mocks.dashboard).toHaveBeenCalledWith(expect.objectContaining({ kind: "alert", page: 1 }));
    expect(screen.getByRole("table", { name: "Hàng đợi công việc chăm sóc học sinh" })).toBeInTheDocument();
  });

  it("denies a viewer without student_care.view before any read", async () => {
    mocks.permissions.mockResolvedValue({ ok: true, permissions: ["student_care.handle"] });
    render(await StudentCarePage({ searchParams: Promise.resolve({}) }));
    expect(screen.getByText("Không có quyền xem chăm sóc học sinh")).toBeInTheDocument();
    expect(mocks.dashboard).not.toHaveBeenCalled();
    expect(mocks.students).not.toHaveBeenCalled();
  });
});

const detail: CareDetail = {
  assignees: [{ id: ME, name: "Đặng Phương Thảo" }],
  assignment: null,
  available_coaching: [],
  coaching: [],
  contacts: [],
  events: [],
  student: { full_name: "Trần Gia Bảo", id: STUDENT, lifecycle_status: "active", public_code: "TTV-00131" },
  task: {
    claim_due_at: null, completed_at: null, contact_due_at: null, detected_at: "2026-10-12T14:53:00Z", due_at: null, evidence: {},
    evidence_current: true, first_contact_at: null, id: TASK, kind: "followup", next_followup_at: null, outcome: null, owner_id: ME,
    period_month: null, status: "in_progress", student_id: STUDENT, version: 1,
  },
};

describe("/student-care/[taskId] route", () => {
  const open = (taskId: string) => StudentCareDetail({ params: Promise.resolve({ taskId }) });

  it("answers 404 for a bad id or a missing task and an error state for a failed read", async () => {
    allow("student_care.handle");
    mocks.user.mockResolvedValue({ ok: true, user: { id: ME } });
    await expect(open("not-a-uuid")).rejects.toThrow("NEXT_NOT_FOUND");
    expect(mocks.detail).not.toHaveBeenCalled();

    mocks.detail.mockResolvedValueOnce({ data: null, ok: true });
    await expect(open(TASK)).rejects.toThrow("NEXT_NOT_FOUND");

    mocks.detail.mockResolvedValueOnce({ ok: false });
    render(await open(TASK));
    expect(screen.getByText("Không tải được công việc chăm sóc. Vui lòng thử lại.")).toBeInTheDocument();
  });

  it("offers the contact form only with student_care.handle", async () => {
    mocks.user.mockResolvedValue({ ok: true, user: { id: ME } });
    mocks.detail.mockResolvedValue({ data: detail, ok: true });

    allow("student_care.assign");
    render(await open(TASK));
    expect(screen.getByRole("heading", { level: 1, name: "Trần Gia Bảo · Theo dõi tiếp" })).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "Lưu lần liên hệ" })).toBeNull();
    expect(screen.queryByRole("button", { name: "Giao cho người khác" })).toBeNull();
    cleanup();

    allow("student_care.handle");
    render(await open(TASK));
    expect(screen.getByRole("button", { name: "Lưu lần liên hệ" })).toBeInTheDocument();
  });
});
